def descriptor_gather(self, desc, x_offsets, y_offset, cache_modifier: str, eviction_policy: str) -> TensorTy:
    assert isinstance(desc, tl.tensor_descriptor_base)
    assert cache_modifier == "", "cache modifier is not supported yet"
    assert eviction_policy == "", "eviction policy is not supported yet"

    # Validate descriptor.
    assert len(desc.block_shape) == 2, f"descriptor must be 2D, but got {desc.block_shape}"
    assert desc.block_shape[0] == 1, f"descriptor block must have 1 row, but got {desc.block_shape}"

def _convert_to_ir_values(self, list_like, require_i64=True):
    if hasattr(list_like, "__iter__"):
        return [self._convert_elem_to_ir_value(elem, require_i64) for elem in list_like]
    return [self._convert_elem_to_ir_value(list_like, require_i64)]

def make_tensor_descriptor(self, base: TensorTy, shape: List[TensorTy], strides: List[TensorTy],
                           block_shape: List[tl.constexpr], padding_option: str = "zero") -> tl.tensor_descriptor:
    ndim = len(shape)
    if not (1 <= ndim <= 5):
        raise ValueError(f"Expected 1 <= ndim <= 5 but got {ndim} dimensions")
    if len(strides) != ndim:
        raise ValueError(f"Expected {ndim} strides but got {len(strides)}")
    if len(block_shape) != ndim:
        raise ValueError(f"Expected block_shape to have {ndim} dimensions but got {len(strides)}")
    assert isinstance(base.dtype, tl.pointer_type)
    elem_size = base.dtype.element_ty.primitive_bitwidth // 8
    contig_dim_size = tl._unwrap_if_constexpr(block_shape[-1])
    if contig_dim_size * elem_size < 16:
        raise ValueError(
            f"Descriptor block shape must have at least 16 bytes in the last dimension, but got {contig_dim_size} * {elem_size} = {contig_dim_size * elem_size} bytes"
        )

    last_stride = tl._unwrap_if_constexpr(strides[-1])
    if last_stride != 1:
        raise ValueError(f"Tensor descriptor last dim must be 1 but got {last_stride}")

    shape = [self.make_scalar(x, tl.int32) for x in shape]
    strides = [self.make_scalar(tl._unwrap_if_constexpr(x), tl.int64) for x in strides]

    # Check whether `block_shape` is static
    block_shape = tl._unwrap_shape(block_shape)

    assert isinstance(base.type, tl.pointer_type)
    type = tl.block_type(base.type.element_ty, block_shape)
    base_handle = base.handle
    is_signed_int = base.type.element_ty.is_int_signed()

    padding = self._str_to_padding_option(padding_option)

    if base.type.element_ty.is_int() and padding == ir.PADDING_OPTION.PAD_NAN:
        raise ValueError("Padding option `nan` is not supported for integer blocks")

    handle = self.builder.create_make_tensor_descriptor(base_handle, [s.handle for s in shape],
                                                        [s.handle for s in strides], block_shape, is_signed_int,
                                                        padding)
    target = driver.active.get_current_target()
    if target.backend == "tileir":
        return tl.tileir_tensor_descriptor(handle, shape, strides, type, base)
    return tl.tensor_descriptor(handle, shape, strides, type)

# - ^\s*tt\.func\s+ : match the start of the string, any leading whitespace, the keyword func,
#    and any following whitespace
# - (public\s+)? : optionally match the keyword public and any following whitespace
# - (@\w+) : match an @ symbol followed by one or more word characters
#   (letters, digits, or underscores), and capture it as group 1 (the function name)
# - (\((?:%\w+: \S+(?: \{\S+ = \S+ : \S+\})?(?:, )?)*\)) : match a pair of parentheses enclosing
#   zero or more arguments separated by commas, and capture it as group 2 (the argument list)
# - (attributes \{[\S\s]+\})? : optionally match attributes enclosed in braces and capture it as group 3
ptx_prototype_pattern = r"\.(?:visible|extern)\s+\.(?:entry|func)\s+(\w+)\s*\(([^)]*)\)"
prototype_pattern = {
    "ptx": ptx_prototype_pattern,
}

ptx_arg_type_pattern = r"\.param\s+\.(\w+)"
arg_type_pattern = {
    "ptx": ptx_arg_type_pattern,
}


def convert_type_repr(x):
    # Currently we only capture the pointer type and assume the pointer is on global memory.
    # TODO: Capture and support shared memory space
    match = re.search(r'!tt\.ptr<([^,]+)', x)
    tma = re.search(r'tt.nv_tma_desc = 1', x)
    if tma is not None:
        return 'nvTmaDesc'
    x = re.sub(r' {[^}]+}', '', x)
    if match is not None:
        return '*' + convert_type_repr(match.group(1))
    return x


class ASTSource:

    def __init__(self, fn, signature, constexprs=None, attrs=None) -> None:
        self.fn = fn
        self.language = Language.TRITON
        self.ext = "ttir"
        self.name = fn.__name__
        self.signature = signature
        self.constants = dict()
        if constexprs is not None:
            for k, v in constexprs.items():
                k = (fn.arg_names.index(k), ) if isinstance(k, str) else k
                assert isinstance(k, tuple)
                self.constants[k] = v
        self.attrs = attrs or dict()
        for k in self.signature.keys():
            if not isinstance(k, str):
                raise TypeError("Signature keys must be string")

    def hash(self):
        sorted_sig = [v for k, v in sorted(self.signature.items())]
        get_key = lambda x: x.cache_key if hasattr(x, 'cache_key') else str(x)
        constants_key = '-'.join([get_key(v) for k, v in sorted(self.constants.items())])

if isinstance(name, tuple):
    fields = type(name).__dict__.get("_fields", None)
    return tuple_type([str_to_ty(x, c) for x in name], fields)

if name[0] == "*":
    name = name[1:]
    const = False
    if name[0] == "k":
        name = name[1:]
        const = True
    ty = str_to_ty(name, c)
    return pointer_type(element_ty=ty, const=const)

if name.startswith("tensordesc"):
    # Determine mode from type name: tensordesc_im2col vs tensordesc
    is_im2col = name.startswith("tensordesc_im2col")

    inner = name.split("<")[1].rstrip(">")
    dtype, rest = inner.split("[", maxsplit=1)
    block_shape, rest = rest.split("]", maxsplit=1)
    block_shape = [int(s.strip()) for s in block_shape.rstrip("]").split(",")]
    # For im2col, parse optional input_rank=N (e.g., ",input_rank=4,layout")
    tensor_rank = None
    import re as _re
    rank_match = _re.search(r",input_rank=(\d+)", rest)
    if rank_match:
        tensor_rank = int(rank_match.group(1))
        rest = rest[:rank_match.start()] + rest[rank_match.end():]
    layout_str = rest.lstrip(",")
    is_gluon = len(layout_str)
    dtype = str_to_ty(dtype, None)
    # For im2col with tensor_rank, use it for shape/stride types; otherwise use block_shape ndim
    ndim = tensor_rank if (is_im2col and tensor_rank is not None) else len(block_shape)
    shape_type = tuple_type([int32] * ndim)
    # FIXME: Last dim stride should be constexpr(1)
    stride_type = tuple_type(([int64] * ndim))
    block = block_type(dtype, block_shape)
    if target_info.is_tileir():
        return tileir_tensor_descriptor_type(block, shape_type, stride_type)
    if is_gluon:
        from triton.experimental.gluon.language._layouts import NVMMASharedLayout, PaddedSharedLayout, SwizzledSharedLayout
        from triton.experimental.gluon.language.nvidia.hopper.tma import tensor_descriptor_type as nvidia_tensor_descriptor_type
        from triton.experimental.gluon.language.nvidia.hopper.tma import tensor_descriptor_im2col_type as nvidia_tensor_descriptor_im2col_type
        from triton.experimental.gluon.language.amd.gfx1250.tdm import tensor_descriptor_type as amd_tensor_descriptor_type
        layout = eval(
            layout_str,
            dict(NVMMASharedLayout=NVMMASharedLayout, PaddedSharedLayout=PaddedSharedLayout,
                 SwizzledSharedLayout=SwizzledSharedLayout))
        if isinstance(layout, NVMMASharedLayout):
            if is_im2col:
                return nvidia_tensor_descriptor_im2col_type(block, shape_type, stride_type, layout)
            return nvidia_tensor_descriptor_type(block, shape_type, stride_type, layout)
        else:
            return amd_tensor_descriptor_type(block, shape_type, stride_type, layout)
    return tensor_descriptor_type(block, shape_type, stride_type)

from abc import ABCMeta, abstractmethod
import re
from typing import Callable, List, Protocol, Sequence

from triton._utils import find_paths_if
from triton._C.libtriton import make_tensordesc_args


def decompose_descriptor(arg):
    # Currently host-side tensor descriptors are passed as tensor desc + shape + strides.
    # We still need to pass shape/strides after descriptor lowering, so they appear twice.
    return [arg.base, *arg.shape, *arg.strides, arg.padding == "nan", arg.round_f32_to_tf32, *arg.shape, *arg.strides]


def _is_descriptor(arg):
    return isinstance(arg, str) and arg.startswith("tensordesc")


def wrap_handle_tensordesc_impl(launcher, signature, tensordesc_meta, make_tensordesc_arg):
    signature = tuple(signature.values())
    tensordesc_paths = find_paths_if(signature, lambda _, x: _is_descriptor(x))
    if len(tensordesc_paths) == 0:
        return launcher

    # Build a tree to speed up tensordesc type checking, e.g.
    # signature = ('tensordesc', 'i32', ('i32', 'tensordesc'))
    # relevant_paths = {0: {}, 2: {1: {}}}
    relevant_paths = {}
    for path in tensordesc_paths:
        cur = relevant_paths
        for step in path:
            cur = cur.setdefault(step, {})

    def inner(*args):
        base_args = args[:-1]
        kernel_args = args[-1]
        wrapped = make_tensordesc_args(
            kernel_args,
            signature,
            relevant_paths,
            tensordesc_meta,
            base_args,
            make_tensordesc_arg,
        )
        return launcher(*base_args, wrapped)

    return inner


def _parse_descriptor(descriptor):
    match = re.match(r"tensordesc(?:_im2col)?<([^[>]*)\[([^\]]*)\]", descriptor)
    assert match, f"Malformed tensor descriptor type: {descriptor}"

    dtype = match.group(1)
    block_shape = match.group(2)
    block_ndim = block_shape.count(",") + 1

    rank_match = re.search(r",input_rank=(\d+)", descriptor)
    ndim = int(rank_match.group(1)) if rank_match else block_ndim
    return (dtype, ndim)


def _expand_descriptor(descriptor, has_tensordesc_meta, descriptor_type):
    dtype, ndim = _parse_descriptor(descriptor)
    expanded = []

    # If there is no descriptor metadata, the descriptor was decomposed to:
    # base pointer, shape, strides, padding, round_f32_to_tf32.
    if not has_tensordesc_meta:
        expanded.append("*" + dtype)
        for _ in range(2 * ndim):
            expanded.append("i64")
        expanded.append("i1")
        expanded.append("i1")
    else:
        expanded.append(descriptor_type)

    for _ in range(ndim):
        expanded.append("i32")
    for _ in range(ndim):
        expanded.append("i64")
    return expanded


def expand_signature(signature, tensordesc_meta, descriptor_type):
    has_tensordesc_meta = bool(tensordesc_meta)

    result = []

    def visit(signature, result):
        if _is_descriptor(signature):
            result.extend(_expand_descriptor(signature, has_tensordesc_meta, descriptor_type))
            return
        elif isinstance(signature, tuple):
            inner = []
            for s in signature:
                visit(s, inner)
            result.append(tuple(inner))
        else:
            result.append(signature)

    result = []
    for s in signature:
        visit(s, result)
    return result


class Benchmarker(Protocol):

    def __call__(self, kernel_call: Callable, *, quantiles: List[float], **kwargs) -> Sequence[float]:
        pass


class DriverBase(metaclass=ABCMeta):

    @classmethod
    @abstractmethod
    def is_active(self):
        pass

    @abstractmethod
    def map_python_to_cpp_type(self, ty: str) -> str:
        """
        Converts a Triton type string to its corresponding C++ type string for this backend.

        Args:
            ty (str): The Triton type string. e.g., 'i32', '*fp16', 'fp32'.

        Returns:
            str: The C++ type string.
        """
        pass

    @abstractmethod
    def get_current_target(self):
        pass

    @abstractmethod
    def get_active_torch_device(self):
        pass

    @abstractmethod
    def get_benchmarker(self) -> Benchmarker:
        """
        Return the benchmarking function that this backend should use by default.
        """
        raise NotImplementedError

    def allocate_default_profile_scratch(self, size: int, alignment: int, stream):
        """
        Allocate profile scratch when no explicit profile allocator override was installed.
        """
        raise NotImplementedError

    def __init__(self) -> None:
        pass


class GPUDriver(DriverBase):

    def __init__(self):
        # TODO: support other frameworks than torch
        import torch
        self.get_device_capability = torch.cuda.get_device_capability
        try:
            from torch._C import _cuda_getCurrentRawStream
            self.get_current_stream = _cuda_getCurrentRawStream
        except ImportError:
            self.get_current_stream = lambda idx: torch.cuda.current_stream(idx).cuda_stream
        self.get_current_device = torch.cuda.current_device
        self.set_current_device = torch.cuda.set_device

    # TODO: remove once TMA is cleaned up
    def assemble_tensormap_to_arg(self, tensormaps_info, args):
        return args

    def allocate_default_profile_scratch(self, size: int, alignment: int, stream):
        import torch
        device = self.get_active_torch_device()
        device_interface = self.get_device_interface()
        if stream is None:
            return torch.zeros(size, dtype=torch.int8, device=device)
        launch_stream = device_interface.ExternalStream(stream, device=device)
        with device_interface.stream(launch_stream):
            scratch = torch.zeros(size, dtype=torch.int8, device=device)
        scratch.record_stream(launch_stream)
        return scratch
